head.script:
scwin.gVar = {
    "cTabIndexTarget" : "",
    "cTabIndexInput" : "",
    "cTabIndexButton" : "",
    "cTabIndexSelectBox" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > tabIndex]<br/>Tab 키를 사용하여 컴포넌트 간 포커스를 이동할때 Secret 컴포넌트의 순서를 설정합니다.",
    "validation" : [
        "nextTabID 속성 설정 시 tabIndex 속성에 의한 순서는 무시되고 nextTabID 에 설정된 컴포넌트로 포커스가 이동합니다.",
        "미설정 시, Tab 키에 의한 기본 포커스 이동 순서에 포함됩니다.",
        "0 설정 시, Tab 키에 의한 기본 포커스 이동 순서에 포함시킵니다.",
        "Pos Int 설정 시, Tab 키에 의한 포커스 이동 순서를 양의 정수로 설정합니다.",
        "Neg Int 설정 시, Tab 키에 의한 포커스 이동에서 제외합니다.",
        "tabIndex 속성에 의한 포커스 이동 순서는 일반적으로 아래 규칙이 적용됩니다.",
        "양수로 설정된 컴포넌트 중 작은 숫자의 컴포넌트부터 포커스를 받습니다.",
        "같은값인 경우 소스에 정의된 순서대로 포커스가 이동합니다.",
        "양수로 설정된 컴포넌트를 모두 순회한 후 0 또는 미설정 컴포넌트로 포커스가 이동합니다.",
        "미설정 컴포넌트는 포커스를 받을 수 있는 태그인 경우만 포커스 이동 순서에 포함됩니다.",
        "0 또는 미설정 컴포넌트는 소스에 정의된 순서대로 포커스가 이동합니다.",
        "컴포넌트가 포커스를 받을 수 없는 상태이면 tabIndex 속성값에 관계없이 포커스가 이동하지 않습니다.",
    ]
}



// 공통 판(common_P_tabIndex_1) 의 validation 7건으로는 secret 가이드(@tagversion 2.0) 전항목을 덮지 못해 tData 를 덮어쓴다
scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (소스 정의 순서 : startcomp -> target1(Secret) -> input2 -> button2 -> selectbox2 -> tbx_static)
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (scwin.startcomp) {
        scwin.startcomp.remove();
        scwin.startcomp = null;
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof input2 !== 'undefined') {
        input2.remove();
    }

    if (typeof button2 !== 'undefined') {
        button2.remove();
    }

    if (typeof selectbox2 !== 'undefined') {
        selectbox2.remove();
    }

    if (typeof tbx_static !== 'undefined') {
        tbx_static.remove();
    }

    $c.gcm.createLabel('label="[전제] 소스 정의 순서는 startcomp(tabIndex 1 고정) -> target1(Secret) -> input2 -> button2 -> selectbox2 -> tbx_static 이며 tbx_static 은 포커스를 받을 수 없는 태그(tabIndex 미설정)입니다\n[절차] 위 tabIndex 4개 조건 입력 -> Target 재생성 -> 초기포커스이동 클릭 -> Tab 키 반복 / comp disabled 에서 컴포넌트 선택 -> setDisabled 클릭 -> 초기포커스이동 -> Tab 키 반복\n[확인] 재생성 시 출력되는 렌더 tabindex 속성값, Tab 을 누를 때마다 결과창에 쌓이는 onfocus 순서, disabled 로 지정한 컴포넌트의 onfocus 출력 여부로 판정합니다 / nextTabID 병용과 Secret 자신의 포커스 불가 상태는 공통 샘플에 nextTabID 조건과 target1 disabled 선택지가 없어 이 구성에서는 관측할 수 없습니다"', '', 'label1');

    // Tab 순회 출발점 (공통 판의 초기포커스이동 버튼이 objParent.startcomp.focus() 로 호출)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strStartComp = '';

    strStartComp += '<xf:input ' + strNameSpace + ' tabIndex="1" initValue="start" style="width:144px; height:21px;"></xf:input>';

    scwin.startcomp = await $p.dynamicCreate(
        "startcomp",
        "input",
        strStartComp,
        grp_comp
    );

    // 조건 설정 (target1 : Secret)
    let cList = $c.gcm.createCList({ tabIndex : scwin.gVar["cTabIndexTarget"] });

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList, 'ev:onfocus="scwin.target1_onfocus"');

    // 비교 대상 (공통 판이 제공하는 나머지 3개 조건)
    let cListInput = $c.gcm.createCList({ tabIndex : scwin.gVar["cTabIndexInput"] });

    await $c.gcm.createBasicInput(cListInput, 'ev:onfocus="scwin.input2_onfocus"', 'input2');

    let cListButton = $c.gcm.createCList({ tabIndex : scwin.gVar["cTabIndexButton"] });

    await $c.gcm.createBasicButton(cListButton, 'ev:onfocus="scwin.button2_onfocus"', 'button2');

    let cListSelectBox = $c.gcm.createCList({ tabIndex : scwin.gVar["cTabIndexSelectBox"] });

    await $c.gcm.createBasicSelectBox(cListSelectBox, 'ev:onfocus="scwin.selectbox2_onfocus"', 'selectbox2');

    // 포커스를 받을 수 없는 태그(textbox -> DIV) - tabIndex 미설정
    $c.gcm.createLabel('label="tbx_static (포커스를 받을 수 없는 태그, tabIndex 미설정)"', '', 'tbx_static');

    input2.setValue("input");

    scwin.printCompState();
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 렌더된 tabindex 속성값 (속성이 없으면 미설정)
scwin.fn_tabAttr = function (objComp) {
    if (!objComp || !objComp.render)
        return "없음";

    let strAttr = objComp.render.getAttribute("tabindex");

    return (strAttr === null) ? "미설정" : strAttr;
}



// 재생성 시 적용 상태 출력 - 조건값과 렌더 결과의 대조용
scwin.printCompState = function () {
    wf_sample.getObj("wf_body_bottom").getObj("scwin").setReturnValue("tabIndex target1 " + scwin.fn_disp(scwin.gVar["cTabIndexTarget"]) + " / input2 " + scwin.fn_disp(scwin.gVar["cTabIndexInput"]) + " / button2 " + scwin.fn_disp(scwin.gVar["cTabIndexButton"]) + " / selectbox2 " + scwin.fn_disp(scwin.gVar["cTabIndexSelectBox"]) + " -> 렌더 tabindex 속성 : startcomp " + scwin.fn_tabAttr(scwin.startcomp) + ", target1 " + scwin.fn_tabAttr(target1) + ", input2 " + scwin.fn_tabAttr(input2) + ", button2 " + scwin.fn_tabAttr(button2) + ", selectbox2 " + scwin.fn_tabAttr(selectbox2) + ", tbx_static " + scwin.fn_tabAttr(tbx_static));
}
